ok = True
# 1. the lock rules (a whole new file, so it is simply written)
p = "backend/app/services/record_locks.py"
os.makedirs(os.path.dirname(p), exist_ok=True)
cur = open(p, 'rb').read().replace(b'\r\n', b'\n') if os.path.exists(p) else None
if cur == LOCKS: print("same     ", p)
else: open(p, 'wb').write(LOCKS); print("written  ", p)
# 2. small anchored edits in the files that are shared with other work
by = {}
for f, mark, anchor, new in OPS: by.setdefault(f, []).append((mark, anchor, new))
for f, steps in by.items():
    if not os.path.exists(f): print("MISSING  ", f); ok = False; continue
    raw = open(f, 'rb').read().decode('utf-8'); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n')
    for mark, anchor, new in steps:
        if mark in t: print("already  ", f.split('/')[-1], mark); continue
        if t.count(anchor) != 1: print("NO MATCH ", f, mark); ok = False; continue
        t = t.replace(anchor, new, 1); print("applied  ", f.split('/')[-1], mark)
    open(f, 'wb').write((t.replace('\n', '\r\n') if crlf else t).encode('utf-8'))
print()
print("All applied." if ok else "Some edits did not match: paste the lines above and I will fit them to your files.")
